const sql=require("mssql"),fs=require("fs"),path=require("path"),{getSourceConfig:getSourceConfig}=require("./db.helper"),mssqlConfig=getSourceConfig(),CLINIC_ID=1,OUTPUT_FILE=path.resolve(__dirname,"payments_data.json");class PaymentMigrator{constructor(){this.mssqlPool=null}async connect(){this.mssqlPool=await sql.connect(mssqlConfig)}async disconnect(){this.mssqlPool&&await this.mssqlPool.close()}async extractPayments(){try{const t=await this.mssqlPool.request().query("\n            SELECT \n                o.ODEMENO,\n                g.HASTANO,\n                o.GELISNO,\n                o.TARIH,\n                o.MIKTAR,\n                o.ODEMETURU,\n                o.NOTLAR,\n                o.IPTAL\n            FROM HST_ODEMELER o\n            LEFT JOIN HST_GELISLER g ON o.GELISNO = g.GELISNO\n            ORDER BY o.TARIH DESC\n        ");return t.recordset.map((t=>({legacy_id:t.ODEMENO,patient_legacy_id:t.HASTANO,appointment_legacy_id:t.GELISNO||null,amount:parseFloat(t.MIKTAR)||0,payment_date:t.TARIH?new Date(t.TARIH).toISOString().slice(0,19).replace("T"," "):null,payment_type:this.mapPaymentType(t.ODEMETURU),notes:t.NOTLAR||null,status:t.IPTAL?"cancelled":"completed"})))}catch(t){return[]}}mapPaymentType(t){switch(String(t)){case"1":return"credit_card";case"2":return"bank_transfer";default:return"cash"}}async run(){await this.connect();try{const t=await this.extractPayments(),e={clinic_id:1,extracted_at:(new Date).toISOString(),payments:t};fs.writeFileSync(OUTPUT_FILE,JSON.stringify(e,null,2))}finally{await this.disconnect()}}}const migrator=new PaymentMigrator;migrator.run().catch(console.error);